INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d53c89e2e96f520b609f','Amedex PB 2025.pdf','112','Mixed/Unclassified','A 37-year-old epileptic man seeks advice regarding
driving. He was diagnosed with epilepsy five years
ago and was started on carbamazepine; however,
he experienced intermittent seizures despite
treatment. Three months ago, carbamazepine was
switched to phenytoin.He has not had any seizures
