INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('89ad639a09b8442f1cc5','Amedex PB 2025.pdf','231','Mixed/Unclassified','Font Siz: A A A
A 6-month-old male infant is brought to your
clinic by his mother for receiving his third dose of
DTPa vaccine. He has received his previous doses
at 6 weeks and 4 months of age. The child sneezes,
has a runny nose and a fever of 38.2°. Exam
findings are consistent with upper respiratory tract
infection (URTI). According to the mother, last time
he received his DTPa vaccine, he developed a huge
swelling at the injection site. Which one of the
following is the most appropriate management
regarding vaccination with DTPa in this situation?','{"A":"Vaccinate him now.","B":"Vaccinate after his UTRI settles.","C":"Do not give the pertussis component.","D":"Use dTpa instead.","E":"Vaccinate him after 2 months."}',NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-d91aea2a4fa3","duplicate_sources":[{"record_id":"89ad639a09b8442f1cc5","record_type":"text_mcq","source_file":"Amedex PB 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","source_page":231,"source_qid":null},{"record_id":"95c27f48b60a95529357","record_type":"text_mcq","source_file":"Amedex PB 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","source_page":230,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"89ad639a09b8442f1cc5","source_file":"Amedex PB 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","source_year":2025,"source_page":231,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Font Siz: A A A\nA 6-month-old male infant is brought to your\nclinic by his mother for receiving his third dose of\nDTPa vaccine. He has received his previous doses\nat 6 weeks and 4 months of age. The child sneezes,\nhas a runny nose and a fever of 38.2°. Exam\nfindings are consistent with upper respiratory tract\ninfection (URTI). According to the mother, last time\nhe received his DTPa vaccine, he developed a huge\nswelling at the injection site. Which one of the\nfollowing is the most appropriate management\nregarding vaccination with DTPa in this situation?","options":{"A":"Vaccinate him now.","B":"Vaccinate after his UTRI settles.","C":"Do not give the pertuss