INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('74ae07719f52268fdec9','Amedex PB 2025.pdf','331','Mixed/Unclassified','Daniel, 52 years old, is in your office with complaint
of excessive daytime sleepiness for the past
six months. He says he has never felt his night
sleeps refreshing enough, and he takes every
opportunity to take a nap during the day. On further
questioning, he admits to snoring and that some
nights his wife leaves the bedroom to sleep on the
couch in the living room because his snoring does
not let her sleep, and in fact, she has made him to
see you for this problem. He denies smoking or any
other significant medical condition. On examination,
his blood pressure is 150/88 mmHg, pulse rate of 80
bpm and respiratory rate of 17 breaths per minute.
He has a BMI of 37 and waist circumference of 135
cm. The rest of the examination is inconclusive. You
suspect sleep apnea as the diagnosis, and arrange
for him to see a sleep specialist. You advise him not
to drive until a full assessment is undertaken by the
specialist, including sleep studies. He becomes upset
and says he cannot stop driving as this is his job.
