INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fd909a590c676f634786','Amedex PB 2025.pdf','341','Mixed/Unclassified','Option B is correct
The five important steps in consulting every patient with
drug, alcohol or smoking problems are known as the 5
‘A''s (ask, assess, advice, assist and arrange).
One important part is assessing the degree of
dependence to that drug. For smokers trying to quit,
assessment of dependence is a key step in management
because it determines whether pharmacotherapy
(nicotine, bupropion, or varenicline [Champix®]) or a
combination of these is required assist the patient in
quitting smoking.
While patients who are not nicotine dependent are
managed non-pharmacologically by counselling,
cognitive and behavioral coping strategies, written
information (e.g. Quit Pack), those with dependence
need pharmacotherapy to increase the chances of
successful quit attempt.
In assessment of dependence, the following
questions should be asked:
¢ How many minutes after waking to you smoke
your first cigarette?','{"A":"How many cigarettes do you smoke a day?","B":"Have you had cravings or withdrawal symptoms in\nprevious quit attempts?\nThe following strongly indicate nicotine dependence and\nthe need for pharmacotherapy:","C":"Smoking with 30 minutes of waking.\n¢ Smoking more than 10 cigarettes a day.\n¢ Craving or withdrawal symptoms in previous","D":"attempt.","E":"Raced on the ah Ne otharany"}',NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-a3f9b9fa37bd","duplicate_sources":[{"record_id":"fd909a590c676f634786","record_type":"text_mcq","source_file":"Amedex PB 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","source_page":341,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"fd909a590c676f634786","source_file":"Amedex PB 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","source_year":2025,"source_page":341,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Option B is correct\nThe five important steps in consulting every patient with\ndrug, alcohol or smoking problems are known as the 5\n‘A''s (ask, assess, advice, assist and arrange).\nOne important part is assessing the degree of\ndependence to that drug. For smokers trying to quit,\nassessment of dependence is a key step in management\nbecause it determines whether pharmacotherapy\n(nicotine, bupropion, or varenicline [Champix®]) or a\ncombination of these is required assist the patient in\nquitting smoking.\nWhile patients who are not nicotine dependent are\nmanaged non-pharmacologically by counselling,\ncognitive and behavioral coping strategies, written\ninformation (e.g. Quit Pack), those with dependence\nneed pharmacotherapy to increase the chances of\nsuccessful quit attempt.\nIn assessment of dependence, the following\nquestions should be asked:\n¢ How many minutes after waking to you smoke\nyour first cigarette?","options":{"A":"How many cigarettes do you smoke a day?","B":"Have you had cravings or withdrawal symptoms in\nprevious quit attempts?\nThe following strongly indicate nicotine dependence and\nthe need for pharmacotherapy:","C":"Smoking with 30 minutes of waking.\n¢ Smoking more than 10 cigarettes a day.\n¢ Craving or withdrawal symptoms in previous","D":"attempt.","E":"Raced on the ah Ne otharany"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","management","therapy"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a3f9b9fa37bd461750119531b3584e0bca1011d7","duplicate_group_id":"exact-a3f9b9fa37bd","duplicate_sources":[{"record_id":"fd909a590c676f634786","record_type":"text_mcq","source_file":"Amedex PB 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex PB 2025.pdf","source_page":341,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evid