INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b9c065d96d89e7a97481','Amedex PB 2025.pdf','404','Mixed/Unclassified','1A 35-year-old Caucasian lady comes to your GP
practice for a follow-up. She initially had a BMI of 32
kg/m2 and was referred to a dietician for nutritional
advice. She otherwise has no comorbid but has a
strong family history of type 2 diabetes mellitus. She
has come to you 6 months later feeling discontented
with her weight loss of 1.5kg. She tells you that she is
